def priority_fn(item_size, open_bin_remaining_capacities, capacity):
    """Improved heuristic combining tight-fit preference with avoidance of awkward residual space."""
    rem = np.asarray(open_bin_remaining_capacities, dtype=float)
    if rem.size == 0:
        return np.array([0.0])

    gaps = rem - item_size
    # Exact fit is ideal; otherwise penalize large residual gaps heavily,
    # with a non-linear preference for leaving either minimal gap or a gap large enough for another item.
    scores = -gaps - 0.1 * (gaps ** 1.5) / capacity
    new_bin_score = -capacity - 1.0
    return np.append(scores, new_bin_score)
